ausdruck = term { ("+" | "-") term } ;
term     = faktor { ("*" | "/") faktor } ;
faktor   = zahl | "(" ausdruck ")" ;
zahl     = ziffer { ziffer } ;
ziffer   = "0" | "1" | ... | "9" ;

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def art(self):     # Art des Tokens
        return self.tokens[self.pos][0]

    def sieh(self):    # Wert des Tokens
        return self.tokens[self.pos][1]

    def weiter(self):
        self.pos += 1

    def parse(self):
        wert = self.ausdruck()
        if self.art() != "ENDE":
            raise SyntaxError(
                f"Unerwartet: {self.sieh()}")
        return wert

    # ausdruck = term {("+"|"-") term}
    def ausdruck(self):
        wert = self.term()
        while self.sieh() in ("+", "-"):
            op = self.sieh()
            self.weiter()
            rechts = self.term()
            if op == "+":
                wert = wert + rechts
            else:
                wert = wert - rechts
        return wert

    # term = faktor {("*"|"/") faktor}
    def term(self):
        wert = self.faktor()
        while self.sieh() in ("*", "/"):
            op = self.sieh()
            self.weiter()
            rechts = self.faktor()
            if op == "*":
                wert = wert * rechts
            else:
                wert = wert / rechts
        return wert

    # faktor = zahl | "(" ausdruck ")"
    def faktor(self):
        wert = self.sieh()
        if self.art() == "ZAHL":
            self.weiter()
            return wert
        if wert == "(":
            self.weiter()
            ergebnis = self.ausdruck()
            if self.sieh() != ")":
                raise SyntaxError("')' fehlt")
            self.weiter()
            return ergebnis
        raise SyntaxError(
            f"Zahl erwartet: {wert}")
